package com.onebytelabs.zlplay.remote;
import java.net.*;import java.io.*;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Native TLS transport. The WebView never receives the pairing code, token or private file access. */
public final class RemoteClient implements AutoCloseable {
 public interface Listener {void state(JSONObject state);void disconnected();}
 private final String address,device;private final Listener listener;private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();private final LinkedHashMap<String,JSONObject> commands=new LinkedHashMap<>();private volatile boolean closed,connected;private volatile JSONObject state=new JSONObject();private String fingerprint,token;
 public RemoteClient(String address,String device,Listener listener){this.address=address;this.device=device;this.listener=listener;}
 private static String digest(java.security.cert.Certificate certificate)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(certificate.getEncoded());StringBuilder hex=new StringBuilder();for(byte value:bytes)hex.append(String.format(java.util.Locale.ROOT,"%02x",value&255));return hex.toString();}
 private static URL endpoint(String address,String path)throws Exception{URL url=new URL("https://"+address+path);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||url.getQuery()!=null||url.getRef()!=null||!url.getPath().equals(path))throw new IOException("Address");for(InetAddress ip:InetAddress.getAllByName(url.getHost())){byte[] bytes=ip.getAddress();boolean ula=bytes.length==16&&(bytes[0]&254)==252;if(!(ip.isLoopbackAddress()||ip.isSiteLocalAddress()||ip.isLinkLocalAddress()||ula))throw new IOException("Local network only");}return url;}
 private static JSONObject request(String address,String path,String pin,String token,JSONObject body,String[] observed)throws Exception{SSLContext tls=SSLContext.getInstance("TLS");tls.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] chain,String auth)throws CertificateException{try{if(chain.length<1)throw new CertificateException();chain[0].checkValidity();String actual=digest(chain[0]);if(pin!=null&&!MessageDigest.isEqual(actual.getBytes(java.nio.charset.StandardCharsets.US_ASCII),pin.getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new CertificateException("Certificate changed");if(observed!=null)observed[0]=actual;}catch(Exception e){throw new CertificateException(e);}}}},new SecureRandom());HttpsURLConnection connection=(HttpsURLConnection)endpoint(address,path).openConnection();connection.setSSLSocketFactory(tls.getSocketFactory());connection.setHostnameVerifier((host,session)->{try{return pin==null||digest(session.getPeerCertificates()[0]).equals(pin);}catch(Exception e){return false;}});connection.setConnectTimeout(2500);connection.setReadTimeout(path.equals("/v1/pair")?45000:3000);connection.setInstanceFollowRedirects(false);if(token!=null)connection.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] data=body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);connection.setFixedLengthStreamingMode(data.length);try(OutputStream out=connection.getOutputStream()){out.write(data);}}int code=connection.getResponseCode();if(code!=200)throw new IOException("Remote status "+code);try(InputStream in=connection.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(out.size()+n>600000)throw new IOException("Snapshot too large");out.write(block,0,n);}JSONObject result=new JSONObject(out.toString("UTF-8"));return result;}}finally{connection.disconnect();}}
 public static String probe(String address)throws Exception{String[] observed=new String[1];JSONObject hello=request(address,"/v1/hello",null,null,null,observed);if(hello.optInt("protocol")!=1||observed[0]==null)throw new IOException("Protocol");return observed[0];}
 public void pair(String code,String fingerprint,Runnable ready,java.util.function.Consumer<Exception> failure){worker.execute(()->{try{this.fingerprint=fingerprint;JSONObject response=request(address,"/v1/pair",fingerprint,null,new JSONObject().put("key",code).put("device",device),null);token=response.getString("token");if(!token.matches("[a-f0-9]{64}"))throw new IOException("Token");state=response.getJSONObject("state");if(closed)return;connected=true;listener.state(state);ready.run();worker.scheduleWithFixedDelay(this::poll,150,200,TimeUnit.MILLISECONDS);}catch(Exception e){failure.accept(e);}});}
 public synchronized void send(JSONObject command){if(closed||!connected)return;try{String type=command.getString("type");command.put("id",UUID.randomUUID().toString()).put("projectId",state.getString("projectId"));String key=type+":"+command.optInt("track",999);if(commands.size()<32||commands.containsKey(key))commands.put(key,command);}catch(JSONException ignored){}}
 private void poll(){if(closed)return;try{List<JSONObject> pending;synchronized(this){pending=new ArrayList<>(commands.values());commands.clear();}for(JSONObject command:pending){if(!state.optString("projectId").equals(command.optString("projectId")))continue;state=request(address,"/v1/command",fingerprint,token,command,null);listener.state(state);}long sent=android.os.SystemClock.elapsedRealtime();state=request(address,"/v1/state",fingerprint,token,null,null);state.put("roundTripMs",android.os.SystemClock.elapsedRealtime()-sent);connected=true;listener.state(state);}catch(Exception e){synchronized(this){commands.clear();}if(connected){connected=false;listener.disconnected();}}}
 public synchronized void close(){if(closed)return;closed=true;connected=false;synchronized(this){commands.clear();}if(token!=null)worker.execute(()->{try{request(address,"/v1/disconnect",fingerprint,token,new JSONObject(),null);}catch(Exception ignored){}});worker.shutdown();}
}
